import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.DBU8LMUS.js";const k=JSON.parse('{"title":"Impor & Ekspor CSV","description":"","frontmatter":{"title":"Impor & Ekspor CSV","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/admin/impor-ekspor.md","filePath":"latest/admin/impor-ekspor.md","lastUpdated":1786334463000}'),o={name:"latest/admin/impor-ekspor.md"};function r(l,a,s,d,m,p){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="impor-ekspor-csv" tabindex="-1">Impor &amp; Ekspor CSV <a class="header-anchor" href="#impor-ekspor-csv" aria-label="Permalink to &quot;Impor &amp; Ekspor CSV&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Admin dengan kemampuan <code>import_export</code> dapat <strong>mengekspor</strong> data alumni ke berkas CSV dan <strong>mengimpor</strong> data alumni dalam jumlah banyak dari berkas CSV. Fitur ini berguna untuk pendataan awal dan pencadangan data.</p><h2 id="mengekspor-data-alumni-csv" tabindex="-1">Mengekspor Data Alumni (CSV) <a class="header-anchor" href="#mengekspor-data-alumni-csv" aria-label="Permalink to &quot;Mengekspor Data Alumni (CSV)&quot;">​</a></h2><ol><li>Masuk dengan akun yang memiliki kemampuan <code>import_export</code>.</li><li>Buka halaman <strong>Admin</strong>, lalu pilih menu <strong>Ekspor CSV</strong>.</li><li>Klik tombol <strong>Ekspor</strong>.</li><li>Berkas CSV berisi data alumni akan diunduh ke perangkat Anda.</li></ol><p>Berkas hasil ekspor dapat dibuka dengan aplikasi pengolah lembar kerja (misalnya Microsoft Excel atau Google Sheets).</p><h2 id="mengunduh-template-impor" tabindex="-1">Mengunduh Template Impor <a class="header-anchor" href="#mengunduh-template-impor" aria-label="Permalink to &quot;Mengunduh Template Impor&quot;">​</a></h2><p>Template impor adalah berkas CSV kosong yang hanya berisi baris judul kolom. Gunakan template ini agar format impor selalu benar.</p><ol><li>Buka halaman <strong>Impor CSV</strong> pada panel admin.</li><li>Klik tombol <strong>Unduh Template</strong>.</li><li>Berkas <code>template.csv</code> akan diunduh.</li></ol><h2 id="format-template-impor" tabindex="-1">Format Template Impor <a class="header-anchor" href="#format-template-impor" aria-label="Permalink to &quot;Format Template Impor&quot;">​</a></h2><p>Template impor berisi <strong>8 kolom</strong> dengan urutan berikut (pemisah titik koma <code>;</code>):</p><table tabindex="0"><thead><tr><th>Kolom</th><th>Keterangan</th></tr></thead><tbody><tr><td><code>nama</code></td><td>Nama lengkap alumni.</td></tr><tr><td><code>angkatan</code></td><td>Tahun angkatan (contoh <code>2015</code>).</td></tr><tr><td><code>tahun_lulus</code></td><td>Tahun kelulusan (contoh <code>2019</code>).</td></tr><tr><td><code>pekerjaan</code></td><td>Jabatan atau profesi saat ini.</td></tr><tr><td><code>perusahaan</code></td><td>Nama perusahaan tempat bekerja.</td></tr><tr><td><code>email</code></td><td>Alamat email alumni.</td></tr><tr><td><code>no_telepon</code></td><td>Nomor telepon.</td></tr><tr><td><code>status_open_to_work</code></td><td>Status terbuka terhadap tawaran kerja: <code>true</code> atau <code>false</code>.</td></tr></tbody></table><h3 id="contoh-isi-template" tabindex="-1">Contoh Isi Template <a class="header-anchor" href="#contoh-isi-template" aria-label="Permalink to &quot;Contoh Isi Template&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nama;angkatan;tahun_lulus;pekerjaan;perusahaan;email;no_telepon;status_open_to_work</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Budi Santoso;2015;2019;Electrical Engineer;PLN;budi@contoh.com;081234567890;true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Siti Aminah;2016;2020;Data Analyst;Telkom;siti@contoh.com;081298765432;false</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Penting</p><ul><li>Gunakan <strong>titik koma (<code>;</code>)</strong> sebagai pemisah kolom, bukan koma.</li><li><strong>Baris pertama</strong> adalah judul kolom dan tidak akan diimpor sebagai data.</li><li>Jangan menambahkan kolom lain di luar 8 kolom tersebut.</li></ul></div><h2 id="mengimpor-data-alumni" tabindex="-1">Mengimpor Data Alumni <a class="header-anchor" href="#mengimpor-data-alumni" aria-label="Permalink to &quot;Mengimpor Data Alumni&quot;">​</a></h2><h3 id="menyiapkan-berkas" tabindex="-1">Menyiapkan Berkas <a class="header-anchor" href="#menyiapkan-berkas" aria-label="Permalink to &quot;Menyiapkan Berkas&quot;">​</a></h3><ol><li>Unduh template impor.</li><li>Isi data alumni pada template menggunakan aplikasi pengolah lembar kerja.</li><li>Simpan berkas dalam format <strong>CSV</strong>.</li></ol><h3 id="melakukan-impor" tabindex="-1">Melakukan Impor <a class="header-anchor" href="#melakukan-impor" aria-label="Permalink to &quot;Melakukan Impor&quot;">​</a></h3><ol><li>Buka halaman <strong>Impor CSV</strong> pada panel admin.</li><li>Pilih berkas CSV yang sudah diisi.</li><li>Klik tombol <strong>Impor</strong>.</li><li>Tunggu hingga proses selesai; sistem menampilkan ringkasan hasil impor.</li></ol><h3 id="perilaku-saat-impor" tabindex="-1">Perilaku Saat Impor <a class="header-anchor" href="#perilaku-saat-impor" aria-label="Permalink to &quot;Perilaku Saat Impor&quot;">​</a></h3><ul><li><strong>Status verifikasi</strong> setiap alumni diimpor otomatis menjadi <strong><code>false</code></strong> (belum terverifikasi).</li><li><strong>Tanggal dibuat</strong> (<code>created_at</code>) diisi otomatis dengan <strong>waktu impor</strong>.</li><li>Alumni dengan email yang sudah terdaftar diperbarui datanya (atau ditandai sesuai aturan sistem).</li></ul><h2 id="penanganan-data-tidak-valid" tabindex="-1">Penanganan Data Tidak Valid <a class="header-anchor" href="#penanganan-data-tidak-valid" aria-label="Permalink to &quot;Penanganan Data Tidak Valid&quot;">​</a></h2><p>Jika terdapat baris yang gagal diimpor (misalnya email tidak valid atau kolom kosong), sistem menampilkan daftar baris yang bermasalah beserta alasannya. Perbaiki baris tersebut pada berkas lalu impor ulang.</p><h2 id="verifikasi-setelah-impor" tabindex="-1">Verifikasi Setelah Impor <a class="header-anchor" href="#verifikasi-setelah-impor" aria-label="Permalink to &quot;Verifikasi Setelah Impor&quot;">​</a></h2><p>Karena status verifikasi otomatis <strong>belum terverifikasi</strong>, lakukan langkah berikut:</p><ol><li>Periksa hasil impor pada halaman <strong>Kelola Alumni</strong>.</li><li>Validasi kebenaran data.</li><li>Gunakan <strong>Verifikasi Massal</strong> untuk memverifikasi data yang sudah dipastikan valid.</li></ol><p>Lanjutkan ke <a href="/webapps/latest/troubleshooting">Pemecahan Masalah</a> untuk membantu mengatasi kendala umum.</p>`,28)])])}const h=e(o,[["render",r]]);export{k as __pageData,h as default};
